 * Position-tracking cursor over the source text's code points. Advancing
 * applies the line-feed and tab column rules the specification defines;
 * every other code point simply moves the column forward by one.
 */
export class Scanner {
  constructor(input) {
    this.chars = [...input]
    this.i = 0
    this.line = 1
    this.col = 1
  }

  get length() {
    return this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const c = this.chars[this.i]
    this.i++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
    return c
  }
}

export class LexError extends Error {
  constructor(pos, reason) {
    super(reason)
    this.pos = pos
  }
}
"}

