const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const isLetter = (c) => c !== undefined && /[A-Za-z_]/.test(c)
const isWordChar = (c) => c !== undefined && /[A-Za-z0-9_]/.test(c)
const isDecDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHexDigit = (c) => c !== undefined && /[0-9a-fA-F]/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c !== undefined && c >= '0' && c <= '7'

/**
 * Consumes a run of digits accepted by `isDigit`, allowing a single `_`
 * between two digits of the run and nowhere else. Returns the consumed
 * source text and how many digits (excluding underscores) were found.
 */
function consumeDigits(s, isDigit) {
  let text = ''
  let count = 0
  for (;;) {
    if (isDigit(s.peek())) {
      text += s.advance()
      count++
      continue
    }
    if (s.peek() === '_' && isDigit(s.peek(1))) {
      text += s.advance()
      text += s.advance()
      count++
      continue
    }
    break
  }
  return { text, count }
}

function skipWhitespaceAndComments(s) {
  for (;;) {
    const c = s.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '/') {
      s.advance()
      s.advance()
      while (s.peek() !== undefined && s.peek() !== '\n') s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '*') {
      const start = s.pos()
      s.advance()
      s.advance()
      let depth = 1
      while (depth > 0) {
        if (s.i >= s.length) throw new LexError(start, 'unterminated block comment')
        if (s.peek() === '*' && s.peek(1) === '/') {
          s.advance()
          s.advance()
          depth--
          continue
        }
        if (s.peek() === '/' && s.peek(1) === '*') {
          s.advance()
          s.advance()
          depth++
          continue
        }
        s.advance()
      }
      continue
    }
    break
  }
}

function scanIdent(s, pos) {
  let text = s.advance()
  while (isWordChar(s.peek())) text += s.advance()
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { line: pos.line, col: pos.col, kind, text }
}

function scanNumber(s, pos) {
  let text = s.advance()

  if (text === '0' && /[xXbBoO]/.test(s.peek() || '')) {
    const marker = s.peek()
    text += s.advance()
    const digitFn = /[xX]/.test(marker) ? isHexDigit : /[bB]/.test(marker) ? isBinDigit : isOctDigit
    const { text: dtext, count } = consumeDigits(s, digitFn)
    text += dtext
    if (count === 0) {
      while (isWordChar(s.peek())) text += s.advance()
      throw new LexError(pos, `invalid number ${text}`)
    }
  } else {
    const { text: dtext } = consumeDigits(s, isDecDigit)
    text += dtext

    if (s.peek() === '.' && isDecDigit(s.peek(1))) {
      text += s.advance()
      const { text: ftext } = consumeDigits(s, isDecDigit)
      text += ftext
    }

    if (s.peek() === 'e' || s.peek() === 'E') {
      if (isDecDigit(s.peek(1))) {
        text += s.advance()
        const { text: etext } = consumeDigits(s, isDecDigit)
        text += etext
      } else if ((s.peek(1) === '+' || s.peek(1) === '-') && isDecDigit(s.peek(2))) {
        text += s.advance()
        text += s.advance()
        const { text: etext } = consumeDigits(s, isDecDigit)
        text += etext
      }
    }
  }

  if (isWordChar(s.peek())) {
    while (isWordChar(s.peek())) text += s.advance()
    throw new LexError(pos, `invalid number ${text}`)
  }

  return { line: pos.line, col: pos.col, kind: 'number', text }
}

function scanString(s, pos) {
  s.advance() // opening quote
  let decoded = ''
  for (;;) {
    if (s.i >= s.length) throw new LexError(pos, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    if (c === '\n') throw new LexError(s.pos(), 'newline in string')
    if (c === '\\') {
      const bpos = s.pos()
      s.advance() // backslash
      if (s.i >= s.length) throw new LexError(pos, 'unterminated string')
      const e = s.peek()
      if (e === 'n') {
        decoded += '\n'
        s.advance()
      } else if (e === 't') {
        decoded += '\t'
        s.advance()
      } else if (e === 'r') {
        decoded += '\r'
        s.advance()
      } else if (e === '\\') {
        decoded += '\\'
        s.advance()
      } else if (e === '"') {
        decoded += '"'
        s.advance()
      } else if (e === '0') {
        decoded += '\0'
        s.advance()
      } else if (e === 'x') {
        s.advance()
        const h1 = s.peek()
        const h2 = s.peek(1)
        if (isHexDigit(h1) && isHexDigit(h2)) {
          s.advance()
          s.advance()
          decoded += String.fromCharCode(parseInt(h1 + h2, 16))
        } else {
          throw new LexError(bpos, 'invalid escape \\x')
        }
      } else if (e === 'u') {
        s.advance()
        if (s.peek() !== '{') throw new LexError(bpos, 'invalid escape \\u')
        s.advance()
        let hex = ''
        while (isHexDigit(s.peek())) hex += s.advance()
        if (hex.length === 0) throw new LexError(bpos, 'invalid escape \\u')
        if (s.peek() !== '}') throw new LexError(bpos, 'invalid escape \\u')
        s.advance()
        const cp = parseInt(hex, 16)
        if (cp > 0x10ffff) throw new LexError(bpos, 'invalid escape \\u')
        decoded += String.fromCodePoint(cp)
      } else {
        throw new LexError(bpos, `invalid escape \\${e}`)
      }
    } else {
      decoded += c
      s.advance()
    }
  }
  return { line: pos.line, col: pos.col, kind: 'string', text: JSON.stringify(decoded) }
}

function scanRawString(s, pos) {
  s.advance() // r
  s.advance() // opening quote
  let raw = ''
  for (;;) {
    if (s.i >= s.length) throw new LexError(pos, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    raw += c
    s.advance()
  }
  return { line: pos.line, col: pos.col, kind: 'rawstring', text: JSON.stringify(raw) }
}

function scanPunct(s, pos) {
  const two = (s.peek() || '') + (s.peek(1) || '')
  if (TWO_CHAR_PUNCT.has(two)) {
    s.advance()
    s.advance()
    return { line: pos.line, col: pos.col, kind: 'punct', text: two }
  }
  const one = s.peek()
  if (one !== undefined && ONE_CHAR_PUNCT.has(one)) {
    s.advance()
    return { line: pos.line, col: pos.col, kind: 'punct', text: one }
  }
  return null
}

/** Scans the whole input, returning every token or throwing a `LexError`. */
export function scan(input) {
  const s = new Scanner(input)
  const tokens = []
  for (;;) {
    skipWhitespaceAndComments(s)
    if (s.i >= s.length) break
    const pos = s.pos()
    const c = s.peek()
    if (c === '"') {
      tokens.push(scanString(s, pos))
    } else if (c === 'r' && s.peek(1) === '"') {
      tokens.push(scanRawString(s, pos))
    } else if (isLetter(c)) {
      tokens.push(scanIdent(s, pos))
    } else if (isDecDigit(c)) {
      tokens.push(scanNumber(s, pos))
    } else {
      const p = scanPunct(s, pos)
      if (p) {
        tokens.push(p)
      } else {
        throw new LexError(pos, `unexpected character ${c}`)
      }
    }
  }
  return tokens
}
"}

