/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */
import { readFileSync } from 'node:fs'
import { scan, LexError } from './lexer.js'

const KIND_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function usageError() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    usageError()
    return
  }

  const input = readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = scan(input)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.pos.line}:${err.pos.col}: ${err.message}\n`)
      process.exit(2)
      return
    }
    throw err
  }

  if (mode === 'tokens') {
    const lines = tokens.map((t) => `${t.line}:${t.col} ${t.kind} ${t.text}`)
    process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
  } else {
    const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
    for (const t of tokens) counts[t.kind]++
    const lines = KIND_ORDER.map((k) => `${k} ${counts[k]}`)
    lines.push(`total ${tokens.length}`)
    process.stdout.write(lines.join('\n') + '\n')
  }
}

main()
"}

